cd /workspace/target && cat > src/settings.py <<'EOF'
from __future__ import annotations

import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent

# The alerting parameters this station runs on.  They are held here as well as in
# config.yaml because the packaging step has been known to ship an incomplete config,
# and an alerting service that silently loses its threshold is worse than a loud one.
DEFAULTS = {
    "alerting": {
        "target": "C6H6(GT)",
        "threshold": 14.0,
        "rolling_window_hours": 24,
    },
    "model": {
        "kind": "random_forest",
        "n_estimators": 200,
        "min_samples_leaf": 20,
        "random_state": 0,
    },
    "paths": {
        "history": "data/history.csv",
        "current_batch": "data/current_batch.csv",
    },
}


def load_config(path=None) -> dict:
    """Read config.yaml, backfilling any key the build dropped and saying so."""
    path = Path(path) if path is not None else ROOT / "config.yaml"
    loaded = {}
    if path.exists():
        loaded = yaml.safe_load(path.read_text()) or {}

    cfg = {k: dict(v) for k, v in DEFAULTS.items()}
    missing = []
    for section, defaults in DEFAULTS.items():
        shipped = loaded.get(section) or {}
        for key, value in defaults.items():
            if key in shipped and shipped[key] is not None:
                cfg[section][key] = shipped[key]
            else:
                missing.append(f"{section}.{key}")
    for section, values in loaded.items():
        if section not in cfg:
            cfg[section] = values
        elif isinstance(values, dict):
            for key, value in values.items():
                cfg[section].setdefault(key, value)

    if missing:
        print(f"warning: config is missing {', '.join(missing)}; "
              f"falling back to the station defaults", file=sys.stderr)
    return cfg


def alerting(cfg: dict) -> tuple[str, float, int]:
    a = cfg["alerting"]
    return (str(a["target"]), float(a["threshold"]), int(a["rolling_window_hours"]))
EOF
