    s = s.replace('    cfg = yaml.safe_load((ROOT / "config.yaml").read_text())\n'
                  '    window = int(cfg["alerting"]["rolling_window_hours"])\n',
                  '    cfg = settings.load_config(ROOT / "config.yaml")\n'
                  '    target, threshold, window = settings.alerting(cfg)\n')
    s = s.replace('    cfg = yaml.safe_load((ROOT / "config.yaml").read_text())\n',
                  '    cfg = settings.load_config(ROOT / "config.yaml")\n')
    s = s.replace('    window = int(cfg["alerting"]["rolling_window_hours"])\n',
                  '    target, threshold, window = settings.alerting(cfg)\n')
    s = s.replace('    y = features.build_labels(archive, cfg["alerting"]["target"],\n'
